export default function f({ body, headers, expected, companyId, websiteField }) {
  if (!expected || headers.authorization !== expected)
    throw Error("Unauthorized Pipedrive webhook");
  const m = body?.meta,
    d = body?.data;
  if (
    m?.entity !== "organization" ||
    m.action !== "create" ||
    String(m.company_id) !== companyId ||
    !m.entity_id ||
    String(d?.id) !== String(m.entity_id) ||
    !d?.name
  )
    throw Error("Unexpected Pipedrive event");
  const website = d.custom_fields?.[websiteField];
  if (typeof website !== "string" || !/^https?:\/\//i.test(website))
    throw Error("Configure organization website custom field");
  return { orgId: String(d.id), companyId, orgName: String(d.name), website };
}

