export default async function f(
  { companyId, orgId, orgName, website, summary, acknowledge, resolution },
  ctx,
) {
  if (
    !/^\d+$/.test(companyId) ||
    !/^\d+$/.test(orgId) ||
    !orgName ||
    !/^https?:\/\//i.test(website)
  )
    throw Error("Invalid organization");
  const key = "pipedrive-company:" + companyId + ":org:" + orgId;
  let s = await ctx.state.get(key);
  if (s && s.website !== website)
    throw Error("Restore original website while processing this organization");
  if (s?.phase?.endsWith("-pending")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.phase + " " + key);
    if (s.phase === "note-pending")
      s.phase = resolution === "confirmed" ? "slack-ready" : "note-ready";
    else s.phase = resolution === "confirmed" ? "done" : "slack-ready";
    await ctx.state.set(key, s);
  }
  if (!s) {
    if (!summary) return { key, phase: "scrape", note: {}, text: "-" };
    if (!summary.trim()) throw Error("Empty summary");
    s = { phase: "note-ready", website, orgName, summary: summary.trim() };
    await ctx.state.set(key, s);
  }
  if (s.phase === "note-ready") {
    const escape = (x) =>
      x.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    const note = {
      org_id: Number(orgId),
      content: "<p>" + escape(s.summary).replace(/\n/g, "<br>") + "</p>",
    };
    s.phase = "note-pending";
    await ctx.state.set(key, s);
    return { key, phase: "note", note, text: "-" };
  }
  if (s.phase === "slack-ready") {
    s.phase = "slack-pending";
    await ctx.state.set(key, s);
    return {
      key,
      phase: "slack",
      note: {},
      text: "New Pipedrive organization: " + s.orgName + "\n\n" + s.summary,
    };
  }
  if (s.phase === "done") return { key, phase: "done", note: {}, text: "-" };
  throw Error("Invalid state");
}

