export default async function f({ key, status, body, orgId }, ctx) {
  const s = await ctx.state.get(key);
  if (
    s?.phase !== "note-pending" ||
    status < 200 ||
    status >= 300 ||
    !body?.success ||
    !body?.data?.id ||
    String(body.data.org_id) !== orgId
  )
    throw Error("Inspect Pipedrive note");
  s.phase = "slack-ready";
  await ctx.state.set(key, s);
  return { ok: true };
}

