export default async function f({ key, ts }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase !== "slack-pending" || !ts) throw Error("Inspect Slack notification");
  s.phase = "done";
  await ctx.state.set(key, s);
  return { ok: true };
}
